const directory=process.argv[2];if(!directory)throw new Error(`Retired checkout path is required`);const deadline=process.platform===`linux`?performance.now()+3e4:Infinity;const hasIoPressure=createHostIoPressureProbe(directory,process.argv[3]===`resume`);let entries=0;let bytes=0;const MAX_ENTRIES=128;const MAX_BYTES=8388608;async function remove(e){if(performance.now()>=deadline)return false;const t=fs.lstatSync(e,{throwIfNoEntry:false});if(!t)return true;if(t.isDirectory()){const t=fs.opendirSync(e);try{let n;while(n=t.readSync())if(!await remove(path.join(e,n.name)))return false}finally{t.closeSync()}}const n=t.isFile()?t.size:0;if(entries&&(entries>=MAX_ENTRIES||bytes+n>MAX_BYTES)){await setTimeout(100);if(await hasIoPressure())return false;entries=0;bytes=0}if(performance.now()>=deadline)return false;if(t.isDirectory())fs.rmdirSync(e);else fs.unlinkSync(e);entries++;bytes+=n;return true}try{if(await hasIoPressure()||!await remove(directory))process.exitCode=75}catch(e){if(isWorktreePermissionError(e)){process.stderr.write(`Retired checkout permission denied: ${String(e)}\n`);process.exitCode=77}else throw e}export{};